import assert from 'node:assert/strict';
import fs from 'node:fs/promises';

export async function runMotionStreamPlacementSmoke(page,template="showcase-stream"){
 const count=template==='hero-reel'?7:template==='mosaic-wipe'?4:template==='stripe-reveal'||template==='diagonal-wipe'?3:template==='split-reveal'?4:template==='cascade-deck'?8:template==='position-dance'?6:template==='cover-ring'||template==='cover-ring-vertical'?8:template==='cover-flow'||template==='cover-flow-vertical'?5:template==='wheel-spin-bottom'||template==='wheel-spin'?8:template==='wheel-carousel'?6:template==='photo-orbit'?8:template==='poster-burst'||template==='deck-peel'?4:template==='film-strip'||template==='card-totem'?6:template==="iso-orbit"?9:template==="pop-grid"?6:template==="center-stage"?3:template==="carousel-flow"?5:template==="stack-slide"?4:template==="iso-focus-sequence"?10:template==="card-toss"?8:template==="diagonal-carousel"?6:template==="iso-cascade"?10:template==="grid-reveal"?4:template==="zoom-parallax"?3:template==="cascade-drop"?4:template==="focus-shift"?4:12;
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 async function ready(){await page.waitForFunction(count=>{const f=document.querySelector('#preview'),d=f?.contentDocument;const g=d?.querySelector('.nw-stream-group'),e=sec().elements.find(e=>e.id===selection[0]);return g&&e&&d.defaultView.__NAG_SCROLL_DIRECTOR?.[e.id]&&+g.dataset.w===+e.w&&Math.abs(g.clientHeight-e.h)<2&&d?.querySelectorAll('.nw-stream-card').length===count&&d.querySelector('.nw-story-transform-h.size')?.style.display==='block'&&Array.from(d.querySelectorAll('.nw-stream-card')).every(n=>n.width>10)&&(!g.querySelector('.nw-ticker-surface')||Math.abs(g.querySelector('.nw-ticker-surface').width/Math.min(2,d.defaultView.devicePixelRatio||1)-g.clientWidth)<2);},{},count);}
 async function geometry(gid){const handle=await page.waitForFunction(({gid,progress})=>{const f=document.querySelector('#preview'),d=f?.contentDocument,g=d?.querySelector('[data-id="'+gid+'"]'),clock=f?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid],e=sec().elements.find(e=>e.id===gid);if(!g||!clock||!e||+g.dataset.w!==+e.w||Math.abs(g.clientHeight-e.h)>=2)return false;clock.set(progress);return{w:g.clientWidth,h:g.clientHeight,bg:f.contentWindow.getComputedStyle(g).backgroundColor,shadow:f.contentWindow.getComputedStyle(g).boxShadow,scene:f.contentWindow.getComputedStyle(g.closest('.sc')).getPropertyValue('--bg').trim(),cards:Array.from(g.querySelectorAll('[data-nw-stream-slot]'),n=>({id:n.dataset.id,x:(parseFloat(n.style.left)+parseFloat(n.style.width)/2)/g.clientWidth,y:(parseFloat(n.style.top)+parseFloat(n.style.height)/2)/g.clientHeight,w:parseFloat(n.style.width)/g.clientWidth,h:parseFloat(n.style.height)/g.clientHeight}))};},{},{gid,progress:template==='center-stage'?.5:.35});const result=await handle.jsonValue();await handle.dispose();return result;}
 try{
  for(const source of ['time','scroll']){
   await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',height:100,bg:'#527467',sdEnabled:false,elements:[]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
   await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-library-tab="library"]');await page.click('[data-motion-template="'+template+'"]');
   await page.$eval('[data-motion-stream="backgroundType"]',n=>{n.value='none';n.dispatchEvent(new Event('change',{bubbles:true}));});
   if(template==='stack-slide')for(const [key,value] of [['cardRatio','frame'],['depthScale','0.85'],['offsetX','8'],['offsetY','-4']])await page.$eval('[data-motion-stream="'+key+'"]',(n,value)=>{n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},value);
   if(template==='carousel-flow')for(const [key,value] of [['direction','vertical'],['frameRatio','9:16'],['cardRatio','16:9']])await page.$eval('[data-motion-stream="'+key+'"]',(n,value)=>{n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},value);
   if(template==='ticker-loop')for(const [key,value] of [['movement','zoomWaypoints'],['orientation','vertical']])await page.$eval('[data-motion-stream="'+key+'"]',(n,value)=>{n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},value);
   await page.$eval('[data-motion-config="source"]',(n,v)=>{n.value=v;n.dispatchEvent(new Event('change',{bubbles:true}));},source);
   await page.click('[data-motion-insert-group]');const gid=await page.evaluate(()=>{NAGWEB_STORY_TIMELINE_UI.setState({docked:false,minimized:true});return selection[0];});assert.equal(await page.evaluate(id=>sec().elements.find(e=>e.id===id).nwMotionInstance.stream.backgroundType,gid),'none');await ready();
   const start=await geometry(gid),members=await page.evaluate(id=>JSON.stringify(sec().elements.filter(e=>e.parent===id)),gid);assert.equal(start.bg,'rgba(0, 0, 0, 0)');assert.equal(start.shadow,'none');assert.equal(start.scene,'#527467');
   // A real click on a rendered card selects the whole placed composition.
   const cardPoint=await page.$eval('#preview',f=>{
    const fr=f.getBoundingClientRect(),d=f.contentDocument,g=d.querySelector('.nw-stream-group'),gr=g.getBoundingClientRect();
    const visibleCenter=(n,poly)=>{const x=poly.reduce((s,p)=>s+p.x,0)/poly.length,y=poly.reduce((s,p)=>s+p.y,0)/poly.length,clip=n.__nwMotionClip;return !clip||x>clip.left+10&&x<clip.left+clip.width-10&&y>clip.top+10&&y<clip.top+clip.height-10;};
    const candidates=Array.from(g.querySelectorAll('[data-nw-stream-slot]')).filter(n=>n.__nwMotionVisible).sort((a,b)=>+b.style.zIndex-+a.style.zIndex),n=candidates.find(n=>!n.__nwMotionInstances||n.__nwMotionInstances.some(t=>visibleCenter(n,t.polygon)));
    const points=n.__nwMotionInstances?n.__nwMotionInstances.find(t=>visibleCenter(n,t.polygon)).polygon:n.__nwMotionSurface,cx=points.reduce((s,p)=>s+p.x,0)/points.length,cy=points.reduce((s,p)=>s+p.y,0)/points.length;
    return{x:fr.left+(gr.left+cx)*fr.width/f.clientWidth,y:fr.top+(gr.top+cy)*fr.height/f.clientHeight};
   });await page.mouse.click(cardPoint.x,cardPoint.y);await page.waitForFunction(id=>selection.length===1&&selection[0]===id,{},gid);
   const {sx,sy,cx,cy}=await page.$eval('#preview',(f,id)=>{const fr=f.getBoundingClientRect(),d=f.contentDocument,h=d.querySelector('.nw-story-transform-h.size').getBoundingClientRect(),g=d.querySelector('[data-id="'+id+'"]').getBoundingClientRect(),zx=fr.width/f.clientWidth,zy=fr.height/f.clientHeight;return{sx:fr.left+(h.left+h.width/2)*zx,sy:fr.top+(h.top+h.height/2)*zy,cx:fr.left+(g.left+g.width/2)*zx,cy:fr.top+(g.top+g.height/2)*zy};},gid);
   await page.mouse.move(sx,sy);await page.mouse.down();await page.mouse.move(cx+(sx-cx)*.65,cy+(sy-cy)*.65,{steps:6});await page.mouse.up();await page.waitForFunction(id=>sec().elements.find(e=>e.id===id).w<65,{},gid);await ready();
   const after=await geometry(gid);assert.ok(after.w<start.w*.7);assert.ok(Math.abs(after.w/start.w-after.h/start.h)<.005,'Width and height shrink together');for(let i=0;i<count;i++)for(const k of ['x','y','w','h'])assert.ok(Math.abs(start.cards[i][k]-after.cards[i][k])<.015,'Ring card '+i+' preserves proportional '+k);assert.equal(await page.evaluate(id=>JSON.stringify(sec().elements.filter(e=>e.parent===id)),gid),members,'Scaling the composition does not edit its image members');
   await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await (await page.$('#preview')).screenshot({path:'/tmp/nagweb-motion-visuals/'+(template==='iso-orbit'?'iso-orbit':template==='pop-grid'?'pop-grid':template==='center-stage'?'center-stage':template==='orbit-bloom'?'orbit-bloom':template==='ticker-tilt'?'ticker-tilt':template==='ticker-loop'?'ticker-loop':template==='carousel-flow'?'carousel-flow':template==='stack-slide'?'stack-slide':template==='iso-focus-sequence'?'iso-focus':template==='card-toss'?'card-toss':template==='diagonal-carousel'?'diagonal-carousel':template==='iso-cascade'?'iso-cascade':template==='grid-reveal'?'grid-reveal':template==='zoom-parallax'?'zoom-parallax':template==='cascade-drop'?'cascade-drop':template==='focus-shift'?'focus-shift':'stream')+'-placement-'+source+'.png'});const saved=await page.evaluate(()=>JSON.stringify(project));await page.evaluate(id=>{undo();selection=[id];curEl=sec().elements.findIndex(e=>e.id===id);renderPane();syncSelectionToFrame();},gid);await ready();const undone=await geometry(gid);assert.ok(Math.abs(undone.w-start.w)<2);await page.evaluate(id=>{redo();selection=[id];curEl=sec().elements.findIndex(e=>e.id===id);renderPane();syncSelectionToFrame();},gid);await ready();assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved);
   // Cancel restores both dimensions and does not create a history entry.
   const cancelProbe=await page.waitForFunction(id=>{const f=document.querySelector('#preview'),d=f?.contentDocument,w=f?.contentWindow,g=d?.querySelector('[data-id="'+id+'"].nw-stream-group'),h=d?.querySelector('.nw-story-transform-h.size');if(!g||!h||h.style.display!=='block'||selection[0]!==id||!w.__NAG_SCROLL_DIRECTOR?.[id])return false;const r=h.getBoundingClientRect(),x=r.left+7,y=r.top+7,initial=[g.style.width,g.style.height],ev=(t,x,y)=>new w.PointerEvent(t,{bubbles:true,cancelable:true,button:0,clientX:x,clientY:y,pointerId:55});h.dispatchEvent(ev('pointerdown',x,y));w.dispatchEvent(ev('pointermove',x-25,y-25));const during=[g.style.width,g.style.height];w.dispatchEvent(ev('pointercancel',x-25,y-25));return{initial,during,after:[g.style.width,g.style.height]};},{},gid),cancelled=await cancelProbe.jsonValue();await cancelProbe.dispose();assert.notDeepEqual(cancelled.during,cancelled.initial,'Pointer move changes size before cancellation');assert.deepEqual(cancelled.after,cancelled.initial);assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved);
   await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),gid);assert.equal(await page.$eval('[data-motion-stream="backgroundType"]',n=>n.value),'none');await page.click('[data-motion-close]');
   await page.evaluate(()=>{const f=document.createElement('iframe');f.id='stream-placement-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(id=>document.querySelector('#stream-placement-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[id],{},gid);assert.equal(await page.$eval('#stream-placement-export',(f,id)=>f.contentWindow.getComputedStyle(f.contentDocument.querySelector('[data-id="'+id+'"]')).backgroundColor,gid),'rgba(0, 0, 0, 0)');await page.evaluate(()=>document.querySelector('#stream-placement-export').remove());
  }
  console.log(template+' colocado: Sin fondo conserva escena, selección de grupo al clicar una tarjeta, tamaño proporcional por mouse en Loop y Scroll, miembros intactos, cancelación, historial, reapertura y exportación OK');
 }catch(error){await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await page.screenshot({path:'/tmp/nagweb-motion-visuals/stream-placement-failure.png'}).catch(()=>{});throw error;}finally{await page.mouse.up().catch(()=>{});await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#stream-placement-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);}
}
